import { build } from "esbuild";
import { writeFile } from "node:fs/promises";

const result = await build({
  entryPoints: [new URL("./server/worker.ts", import.meta.url).pathname],
  bundle: true,
  platform: "node",
  target: "node22.13",
  format: "cjs",
  write: false,
});
const encoded = Buffer.from(result.outputFiles[0].contents).toString("base64");
const lines = encoded.match(/.{1,100}/g)!.map((line) => JSON.stringify(line));
await writeFile(
  new URL("./server/worker-source.ts", import.meta.url).pathname,
  "// Generated by npm run build. The embedded worker survives Paseo bundle evaluation and relocation.\nconst encoded =\n  " +
    lines.join(" +\n  ") +
    ';\nexport default Buffer.from(encoded, "base64").toString("utf8");\n',
);
console.log("Paseo embedded Node worker: built");
